import type { CSSProperties } from "react";
import {
  Body,
  Column,
  Container,
  Head as EmailHead,
  Html,
  Img,
  Preview,
  Row,
  Section,
  Tailwind,
  Text,
} from "react-email";

import { DefaultFonts } from "@/components/email/font-default";
import { createEmailTailwindConfig } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type ContentAlignment = "left" | "center" | "right";
export type ContentLayout =
  | "title"
  | "paragraph"
  | "two-columns"
  | "two-columns-with-icons";
export type ContentPadding = "regular" | "large";
export type ContentVariant = "small" | "large" | "lead" | "body";

export interface ContentProps {
  alignment?: ContentAlignment;
  column1?: string;
  column2?: string;
  iconAlt1?: string;
  iconAlt2?: string;
  iconSrc1?: string;
  iconSrc2?: string;
  layout?: ContentLayout;
  padding?: ContentPadding;
  text?: string;
  theme?: EmailTheme;
  title?: string;
  variant?: ContentVariant;
}

const colors = {
  background: "#fffffe",
  heading: "#030712",
  muted: "#4b5563",
} as const;

const fontFamily =
  'Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';

const defaultIconSources = [
  emailAsset("social/icon-github.png"),
  emailAsset("social/icon-slack.png"),
] as const;

const getImageMargin = (alignment: ContentAlignment) => {
  if (alignment === "center") {
    return "0 auto 10px";
  }

  if (alignment === "right") {
    return "0 0 10px auto";
  }

  return "0 auto 10px 0";
};

const getTitleTypography = (variant?: ContentVariant) => {
  if (variant === "large") {
    return { fontSize: "30px", lineHeight: "36px" };
  }

  return { fontSize: "24px", lineHeight: "32px" };
};

const getParagraphTypography = (variant?: ContentVariant) => {
  if (variant === "body") {
    return { fontSize: "16px", lineHeight: "24px" };
  }

  return { fontSize: "18px", lineHeight: "28px" };
};

const ContentColumn = ({
  alignment,
  alt,
  fontSize,
  iconSrc,
  index,
  lineHeight,
  text,
  withIcon,
}: {
  alignment: ContentAlignment;
  alt: string;
  fontSize: string;
  iconSrc: string;
  index: 0 | 1;
  lineHeight: string;
  text: string;
  withIcon: boolean;
}) => {
  const columnPadding = index === 0 ? "0 22px 0 0" : "0 0 0 22px";

  return (
    <Column
      className="content-column"
      style={{
        padding: columnPadding,
        verticalAlign: "top",
        width: "50%",
      }}
      width="50%"
    >
      {withIcon ? (
        <Img
          alt={alt}
          height="48"
          src={iconSrc}
          width="48"
          style={{
            display: "block",
            height: "48px",
            margin: getImageMargin(alignment),
            width: "48px",
          }}
        />
      ) : null}
      <Text
        style={{
          color: colors.muted,
          fontFamily,
          fontSize,
          lineHeight,
          margin: 0,
          textAlign: alignment,
        }}
      >
        {text}
      </Text>
    </Column>
  );
};

export const ContentSection = ({
  alignment = "center",
  column1 = "A brief introduction that highlights the key idea in a clear, engaging way.",
  column2 = "A brief introduction that highlights the key idea in a clear, engaging way.",
  iconAlt1 = "GitHub",
  iconAlt2 = "Slack",
  iconSrc1 = defaultIconSources[0],
  iconSrc2 = defaultIconSources[1],
  layout = "paragraph",
  padding = "regular",
  text = "Lead text introduces the reader to the key message of an email. It sets the tone, provides context, and guides attention toward what matters most.",
  title = "Stay in the loop by following us across our social channels.",
  variant,
}: Omit<ContentProps, "theme">) => {
  const horizontalPadding = padding === "large" ? "64px" : "24px";
  const sectionStyle: CSSProperties = {
    backgroundColor: colors.background,
    padding: `44px ${horizontalPadding}`,
  };

  if (layout === "title") {
    const typography = getTitleTypography(variant);

    return (
      <Section style={sectionStyle}>
        <Text
          style={{
            color: colors.heading,
            fontFamily,
            fontSize: typography.fontSize,
            fontWeight: 600,
            lineHeight: typography.lineHeight,
            margin: 0,
            textAlign: alignment,
          }}
        >
          {title}
        </Text>
      </Section>
    );
  }

  const typography = getParagraphTypography(variant);

  if (layout === "two-columns" || layout === "two-columns-with-icons") {
    const withIcons = layout === "two-columns-with-icons";

    return (
      <Section style={sectionStyle}>
        <Row>
          <ContentColumn
            alignment={alignment}
            alt={iconAlt1}
            fontSize={typography.fontSize}
            iconSrc={iconSrc1}
            index={0}
            lineHeight={typography.lineHeight}
            text={column1}
            withIcon={withIcons}
          />
          <ContentColumn
            alignment={alignment}
            alt={iconAlt2}
            fontSize={typography.fontSize}
            iconSrc={iconSrc2}
            index={1}
            lineHeight={typography.lineHeight}
            text={column2}
            withIcon={withIcons}
          />
        </Row>
      </Section>
    );
  }

  return (
    <Section style={sectionStyle}>
      <Text
        style={{
          color: colors.muted,
          fontFamily,
          fontSize: typography.fontSize,
          lineHeight: typography.lineHeight,
          margin: 0,
          textAlign: alignment,
        }}
      >
        {text}
      </Text>
    </Section>
  );
};

export const Content = ({
  alignment = "center",
  column1,
  column2,
  iconAlt1,
  iconAlt2,
  iconSrc1,
  iconSrc2,
  layout = "paragraph",
  padding = "regular",
  text,
  theme = defaultTheme,
  title,
  variant,
}: ContentProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style
        dangerouslySetInnerHTML={{
          __html: `
            @media only screen and (max-width: 600px) {
              .content-column {
                display: block !important;
                padding: 0 0 44px !important;
                width: 100% !important;
              }
              .content-column:last-child { padding-bottom: 0 !important; }
            }
          `,
        }}
      />
    </EmailHead>
    <Preview>{layout === "title" ? (title ?? "Title") : "Content"}</Preview>
    <Tailwind config={createEmailTailwindConfig(theme)}>
      <Body style={{ backgroundColor: colors.background }} className="m-0">
        <Container className="mx-auto max-w-[600px]">
          <ContentSection
            alignment={alignment}
            column1={column1}
            column2={column2}
            iconAlt1={iconAlt1}
            iconAlt2={iconAlt2}
            iconSrc1={iconSrc1}
            iconSrc2={iconSrc2}
            layout={layout}
            padding={padding}
            text={text}
            title={title}
            variant={variant}
          />
        </Container>
      </Body>
    </Tailwind>
  </Html>
);

Content.PreviewProps = {
  alignment: "center",
  layout: "paragraph",
  padding: "regular",
  theme: defaultTheme,
  variant: "lead",
} satisfies ContentProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
